// spec: specs/edit-listing-save-changes.md (1.1–1.2) · кейс: .qa/tests/edit-listing-save-changes/EDIT-SAVE-01.md
// seed: tests/seed.user.spec.ts · ПРОД: все не-GET блокируются (мастер создаёт черновик на 1→2), ничего не нажимается.
import { test, expect } from '@playwright/test';
import { blockWrites, LOAD, NEXT, SAVE, TITLE_PH } from './edit-listing.helpers';

test.use({ storageState: '../auth/user.json', serviceWorkers: 'block' });

test.describe('Редактирование объявления — «שמור שינויים» (#357a06)', () => {
  for (const device of ['@desktop', '@android']) {
    test(`Новое объявление — на шаге 1 нет «שמור שינויים» #357a06 ${device} @prod-safe`, async ({ page }) => {
      const passed = await blockWrites(page);
      await page.goto('/addbusiness');
      await expect(page.getByPlaceholder(TITLE_PH), 'шаг 1 открыт').toBeVisible(LOAD);
      await expect(page.getByRole('button', { name: NEXT }), '«שלב הבא» есть').toBeVisible();
      await expect(page.getByRole('heading', { name: 'עריכת מודעה' }), 'это не режим редактирования').toHaveCount(0);
      // «מה רצוי»: кнопка — «במצב עריכה של מודעה קיימת»
      await expect(page.getByRole('button', { name: SAVE }), `«${SAVE}» нет при создании`).toHaveCount(0);
      await expect(page.getByText(SAVE, { exact: true }), `текста «${SAVE}» нет`).toHaveCount(0);
      expect(passed, 'ни один не-GET запрос не дошёл до прода').toEqual([]);
    });
  }
});
